<?php
namespace App\Http\Controllers;
use App\Models\InventoryTransaction; use App\Services\InventoryService; use Illuminate\Http\Request;
class InventoryController { public function index(InventoryService $i){return view('admin.inventory.index',['products'=>$i->allBalances(),'transactions'=>InventoryTransaction::with('product','recorder')->latest('transaction_date')->latest()->paginate(15)]);} public function history(){return view('admin.inventory.history',['transactions'=>InventoryTransaction::with('product','recorder')->latest('transaction_date')->latest()->paginate(20)]);} public function store(Request $r,InventoryService $i){$d=$r->validate(['product_id'=>'required|exists:egg_products,id','transaction_type'=>'required|in:addition,deduction,adjustment','quantity'=>'required|integer|min:1','adjustment_sign'=>'nullable|in:-1,1','reason'=>'required|string|max:150','remarks'=>'nullable|string']); if($d['transaction_type']==='adjustment')$d['quantity']=(int)($d['adjustment_sign']??1)*(int)$d['quantity']; if($d['transaction_type']==='deduction' && $i->balance((int)$d['product_id'])<(int)$d['quantity'])return back()->withErrors(['quantity'=>'Deduction exceeds current inventory.'])->withInput(); InventoryTransaction::create(['product_id'=>$d['product_id'],'transaction_type'=>$d['transaction_type'],'quantity'=>$d['quantity'],'reason'=>$d['reason'],'transaction_date'=>now()->toDateString(),'recorded_by'=>$r->user()->id,'remarks'=>$d['remarks']??null]); return back()->with('success','Inventory transaction saved.');} }
